INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('1eac07fe8aecf8370596','AMEDEX 2025 Respiratory  (1).pdf','40','Respiratory','A 68-year-old woman, with a history of stage
IV chronic kidney disease (CKD), presents to
the Emergency Department with sudden-
onset acute chest pain and shortness of
breath. The chest pain is pleuretic in nature.
On examination, she has a blood pressure of
130/90 mmHg, pulse rate of 120 bpm, and
respiratory rate of 24 cycles per minute. ECG
Shows no abnormalities. A chest X-ray is
obtained that is completely clear. A
ventilation/perfusion scan shows decreased
perfusion in the lower lobe of the left lung.
Which one of the following is the most
