INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('cc3494c1840e6ffce357','AMEDEX 2025 Respiratory  (2).pdf','51','Respiratory','A 67-year-old man with a background history
of smoking for the past 40 years and chronic
obstructive pulmonary disease (COPD)
presents with acute shortness of breath,
pleuretic chest pain, increased mucous
production and severe cough. Last week, he
had an episode of gout in his first
metatarsophalangeal joint, for which he was
Started on indomethacin. Severe pain made
him bedbound for five days. On examination,
he has a blood pressure of 130/95 mmHg,
pulse rate of 110 bpm, respiratory rate of 34
breaths per minute, and temperature of
37.5°C. Which one of the following is the next
best step in management?','{"A":"Chest X-ray.","B":"Arterial blood gas (ABG) analysis.","C":"Computed tomography pulmonary\nangiography (CTPA).","D":"Ventilation/perfusion scan.","E":"Chest CT scan."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-3b35cbc2b29e","duplicate_sources":[{"record_id":"cc3494c1840e6ffce357","record_type":"text_mcq","source_file":"AMEDEX 2025 Respiratory  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","source_page":51,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"cc3494c1840e6ffce357","source_file":"AMEDEX 2025 Respiratory  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","source_year":2025,"source_page":51,"source_qid":null,"domain_hint":"Respiratory","stem":"A 67-year-old man with a background history\nof smoking for the past 40 years and chronic\nobstructive pulmonary disease (COPD)\npresents with acute shortness of breath,\npleuretic chest pain, increased mucous\nproduction and severe cough. Last week, he\nhad an episode of gout in his first\nmetatarsophalangeal joint, for which he was\nStarted on indomethacin. Severe pain made\nhim bedbound for five days. On examination,\nhe has a blood pressure of 130/95 mmHg,\npulse rate of 110 bpm, respiratory rate of 34\nbreaths per minute, and temperature of\n37.5°C. Which one of the following is the next\nbest step in management?","options":{"A":"Chest X-ray.","B":"Arterial blood gas (ABG) analysis.","C":"Computed tomography pulmonary\nangiography (CTPA).","D":"Ventilation/perfusion scan.","E":"Chest CT scan."},"source_answer":null,"source_explanation":null,"source_answer_status":