INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a1397f7c38ceb88f780b','AMEDEX 2025 Respiratory  (2).pdf','95','Respiratory','A 68-year-old nursing home resident man
with long-standing chronic obstructive
pulmonary disease (COPD) has been brought
by ambulance to the emergency department
because of an exacerbation of his condition.
En route to the emergency department, he
was severely short of breath and was given
oxygen 10 L/min via nasal cannula. On
examination, he is drowsy and disoriented.
Which one of the following is most expected
to be his arterial blood gas (ABG) result?','{"A":"Ph=7.29, PaCO2=65mmHg,\nPaO2=85mmHg.","B":"Ph=7.15, PaCO2=50mmuHg,\nPaO2=68mmbHg.","C":"Ph=7.25, PaCO2=25mmHg,\nPaOQ2=100mmbHg.","D":"Ph=7.35, PaCO2=40mmdHg,\nPaO2=40mmbHg.","E":"Ph=7.45, PaCO2=85mmHg,\nPaO2=40mmbHg."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-1a38b842b544","duplicate_sources":[{"record_id":"a1397f7c38ceb88f780b","record_type":"text_mcq","source_file":"AMEDEX 2025 Respiratory  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","source_page":95,"source_qid":null},{"record_id":"5cec7804d003f94f08c5","record_type":"text_mcq","source_file":"AMEDEX 2025 Respiratory  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","source_page":96,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"a1397f7c38ceb88f780b","source_file":"AMEDEX 2025 Respiratory  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","source_year":2025,"source_page":95,"source_qid":null,"domain_hint":"Respiratory","stem":"A 68-year-old nursing home resident man\nwith long-standing chronic obstructive\npulmonary disease (COPD) has been brought\nby ambulance to the emergency department\nbecause of an exacerbation of his condition.\nEn route to the emergency department, he\nwas severely short of breath and was given\noxygen 10 L/min via nasal cannula. On\nexamination, he is drowsy and disoriented.\nWhich one of the following is most expected\nto be his arterial blood gas (ABG) result?","options":{"A":"Ph=7.29, PaCO2=65mmHg,\nPaO2=85mmHg.","B":"Ph=7.15, PaCO2=50mmuHg,\nPaO2=68mmbHg.","C":"Ph=7.25, PaCO2=25mm