INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('337268c574ed65a05c22','AMEDEX 2025 Respiratory  (2).pdf','109','Respiratory','A 5-year-old boy is brought to your practice by
his mother because of intermittent attacks of
wheezing, which have been occurring 4-6 times
a year over the past 2 years. These attacks are
usually precipitated by viral upper respiratory
tract infections and last 2-3 days. The
symptoms respond to treatment with inhaled
salbutamol. There are no interval symptoms.
His older brother had flexural eczema until the
age of 18 months. Which one of the following is
the most appropriate management of this child?','{"A":"Inhaled sodium cromoglycate.","B":"Inhaled fluticasone.","C":"Oral montelukast.","D":"Oral prednisolone when\n\nsymptomatic.","E":"Inhaled salbutamol when\nSymptomatic."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-05884b6d3e40","duplicate_sources":[{"record_id":"337268c574ed65a05c22","record_type":"text_mcq","source_file":"AMEDEX 2025 Respiratory  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","source_page":109,"source_qid":null},{"record_id":"f19d34a5770769935447","record_type":"text_mcq","source_file":"AMEDEX 2025 Respiratory  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","source_page":110,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"337268c574ed65a05c22","source_file":"AMEDEX 2025 Respiratory  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","source_year":2025,"source_page":109,"source_qid":null,"domain_hint":"Respiratory","stem":"A 5-year-old boy is brought to your practice by\nhis mother because of intermittent attacks of\nwheezing, which have been occurring 4-6 times\na year over the past 2 years. These attacks are\nusually precipitated by viral upper respiratory\ntract infections and last 2-3 days. The\nsymptoms respond to treatment with inhaled\nsalbutamol. There are no interval symptoms.\nHis older brother had flexural eczema until the\nage of 18 months. Which one of the following is\nthe most appropriate management of this child?","options":{"A":"Inhaled sodium cromoglycate.","B":"Inhaled fluticasone.","C":"Oral montelukast.","D":"Oral prednisol