Department with sudden-onset chest pain
and shortness of breath. He has chronic
kidney disease and a documented reduced
GFR of 25 ml/min. On examination, his blood
pressure is 110/75mHg and pulse 112 bpm.
An EGG is performed that is normal. A chest
X-ray shows a wedge-shaped opacity in the
periphery of the right lung. Which of the
following should be considered the best
diagnostic tool for this patient?','{"A":"Duplex Doppler ultrasound of\nlower limbs.","B":"D-dimer assay.","C":"Computed tomography pulmonary\nangiography (CTPA).","D":"Arterial blood gas (ABG) analysis.","E":"V/Q scan."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-4d437a9d15a5","duplicate_sources":[{"record_id":"7e39137476c15a59f795","record_type":"text_mcq","source_file":"AMEDEX 2025 Respiratory  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","source_page":116,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"7e39137476c15a59f795","source_file":"AMEDEX 2025 Respiratory  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","source_year":2025,"source_page":116,"source_qid":null,"domain_hint":"Respiratory","stem":"A 62-year-old man presents to the Emergency\nDepartment with sudden-onset chest pain\nand shortness of breath. He has chronic\nkidney disease and a documented reduced\nGFR of 25 ml/min. On examination, his blood\npressure is 110/75mHg and pulse 112 bpm.\nAn EGG is performed that is normal. A chest\nX-ray shows a wedge-shaped opacity in the\nperiphery of the right lung. Which of the\nfollowing should be considered the best\ndiagnostic tool for this patient?","options":{"A":"Duplex Doppler ultrasound of\nlower limbs.","B":"D-dimer assay.","C":"Computed tomography pulmonary\nangiography (CTPA).","D":"Arterial blood gas (ABG) analysis.","E":"V/Q scan."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"4d437a9d15a5a7d111ff3cee1169995759a72885","duplicate_group_id":"exact-4d437a9d15a5","duplicate_sources":[{"record_id":"7e39137476c15a59f795","record_type":"text_mcq","source_file":"AMEDEX 2025 Respiratory  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","source_page":116,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
