INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('cf8a212cee1b3c49b49e','AMEDEX 2025 Respiratory  (2).pdf','122','Respiratory','A 78-year-old man is found unconscious in the
backyard garden by his wife and is brought to
the emergency department. He was diagnosed
with chronic obstructive pulmonary disease
(COPD) 7 years ago and is currently on inhaled
ipratropium bromide. He also has ischemic
heart disease, for which he takes aspirin,
verapamil, and statins. On examination, he is
drowsy and has a blood pressure of 110/70
mmHg, pulse rate of 100 bpm, and respiratory
rate of 24 breaths per minute. On chest
examination, bilateral wheezing is noted.
Bedside pulse-oxymetry shows oxygen
saturation of 85% on room air. An ABG
shows PaO2 of 60 mmHg and PaCO2 of 50
mmHg. Which of the following is the most likely
cause of this clinical picture?','{"A":"Infection.","B":"Electrolyte disturbances.","C":"Sedative overdose.","D":"Left ventricular failure.","E":"Right ventricular failure."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-2d925a693fa1","duplicate_sources":[{"record_id":"cf8a212cee1b3c49b49e","record_type":"text_mcq","source_file":"AMEDEX 2025 Respiratory  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","source_page":122,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"cf8a212cee1b3c49b49e","source_file":"AMEDEX 2025 Respiratory  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","source_year":2025,"source_page":122,"source_qid":null,"domain_hint":"Respiratory","stem":"A 78-year-old man is found unconscious in the\nbackyard garden by his wife and is brought to\nthe emergency department. He was diagnosed\nwith chronic obstructive pulmonary disease\n(COPD) 7 years ago and is currently on inhaled\nipratropium bromide. He also has ischemic\nheart disease, for which he takes aspirin,\nverapamil, and statins. On examination, he is\ndrowsy and has a blood pressure of 110/70\nmmHg, pulse rate of 100 bpm, and respiratory\nrate of 24 breaths per minute. On chest\nexamination, bilateral wheezing is noted.\nBedside pulse-oxymetry shows oxygen\nsaturation of 85% on room air. An ABG\nshows PaO2 of 60 mmHg and PaCO2 of 50\nmmHg. Which of the following is the most likely\ncause of this clinical picture?","options":{"A":"Infection.","B":"Electrolyte disturbances.","C":"Sedative overdose.","D":"Left ventricular failure.","E":"Right ventricular failure."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"2d925a693fa16f04c85655f5278b71ceb34e35f3","duplicate_group_id":"exact-2d925a693fa1","duplicate_sources":[{"record_id":"cf8a212cee1b3c49b49e","record_type":"text_mcq","source_file":"AMEDEX 2025 Respiratory  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Respiratory  (2).pdf","source_page":122,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
