INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('813c1f163548d1fd48c4','AMEDEX 2025 Respiratory  (2).pdf','125','Respiratory','A 45-year-old man, who had hip replacement
Surgery 2 weeks ago, presents with sudden-
onset chest pain and shortness of breath.
Pulse oximetry reveals an oxygen saturation
of 89% on room air. On physical examination,
his blood pressure is 100/75mmHg, heart
rate 113 bpm, respiratory rate 23 breaths per
minute, and temperature 37.3°C. Which of
