INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('489d3e82eacce965c71d','AMEDEX 2025 Urology _ Neurology 1-40 .pdf','117','Neurology','A 58-year-old man is brought to the
emergency department with an ambulance
due to confusion at home noticed by his wife.
He is a known case of chronic kidney disease
(CKD), hypertension, and congestive heart
failure (CHF). He is currently on carvedilol
6.25mg BD, Ramipril 10mg BD, aspirin 100mg
daily, and atorvastatin 10mg daily. On
examination, he has a blood pressure of
148/97mmHg, pulse rate of 98bpm,
respiratory rate of 21 breaths per minute,
and temperature of 37.3°C. He is confused
and disoriented about time, place, and
person. Laboratory tests for him are ordered,
